// machines/plaits: TERRAIN's sample loop (engines/terrain.c, terrain_render), hand-written SISD kernel.
// Generated by lib/gen_terrain_kernel.py; do not edit by hand.
//
// terrain_kernel(Terrain *s, const float *k, float *out, float *aux, const float *path_x, const float *path_y, int size):
//   s = the engine (path_ 4 words, then the interpolators' values offset_, terrain_); k[0..1] = their increments;
//   path_x / path_y = the 2 size oversampled path points. Writes out and aux and the interpolators back,
//   bit-identical to selcc's code of the C loop (-DPL_TERRAIN_C) (tests/plaits/test_terrain_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, I2, I3, I5, M6, L0-L5 pushed through R0, M6 = 1 and L0-L5 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS; integer additions in their 48-bit form.
// Local subroutines: _tk_ter (F10 = x, F11 = y, R12 = terrain index -> F0; changes R0-R8, I4) and _tk_sin
// (F0 = phase -> F0 = terrain_sine(phase); changes R0-R3, I4). R15 = itof_nonneg's bias, R14 = pl_lut_sine,
// R13 = pl_wav_integrated_waves throughout.

.SECTION/PM seg_pmco;
.GLOBAL terrain_kernel.;
.EXTERN pl_lut_sine.;
.EXTERN pl_wav_integrated_waves.;
.COMPRESS;

terrain_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = I3;
    DM(I7, M7) = R0;
    R0 = I5;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L3;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    R0 = L5;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L3 = 0;
    L4 = 0;
    L5 = 0;
    I7=MODIFY (I7,-17)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I5 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(1, I6);                                     // aux
    I1 = R0;
    R0 = DM(2, I6);                                     // path_x
    I2 = R0;
    R0 = DM(3, I6);                                     // path_y
    I3 = R0;
    R0 = DM(4, I6);                                     // size
    DM(9, I7) = R0;
    R15 = 0x4B000000;                                   // bias
    R14 = pl_lut_sine.;
    R13 = pl_wav_integrated_waves.;
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _tk_done;
_tk_loop:
    R0 = DM(4, I5);
    R1 = DM(7, I7);
    F0 = F0 + F1;                                       // x_offset = offset.Next()
    DM(4, I5) = R0;
    DM(10, I7) = R0;
    R2 = DM(5, I5);
    R1 = DM(8, I7);
    F2 = F2 + F1;                                       // zz = terrain_z.Next()
    DM(5, I5) = R2;
    R3 = TRUNC F2;                                      // zz_integral
    DM(12, I7) = R3;
    R4 = R15 OR R3;
    F4 = F4 - F15;
    F2 = F2 - F4;                                       // zz_fractional
    DM(13, I7) = R2;
    R1 = 0;
    DM(14, I7) = R1;                                    // out_s = 0.0f
    DM(15, I7) = R1;                                    // aux_s = 0.0f
    R0 = DM(10, I7);
    R1 = 0;
    F2 = -F0;
    COMP(F0, F1);
    IF GE R2 = R0 OR R0;
    R1 = 0x3F800000;                                    // one
    F2 = F1 - F2;                                       // x = path_x[ij] * (1.0f - absf(x_offset)) + x_offset
    R3 = DM(I2, M6);
    F3 = F3 * F2;
    F10 = F3 + F0;
    R11 = DM(I3, M6);                                   // y = path_y[ij]
    R12 = DM(12, I7);
    CALL _tk_ter;                                       // z0 = terrain(x, y, zz_integral)
    DM(16, I7) = R0;
    R12 = DM(12, I7);
    R1 = 1;
    .NOCOMPRESS;
    R12 = R12 + R1;
    .COMPRESS;
    CALL _tk_ter;                                       // z1 = terrain(x, y, zz_integral + 1)
    R1 = DM(16, I7);
    F0 = F0 - F1;                                       // z = z0 + (z1 - z0) * zz_fractional
    R2 = DM(13, I7);
    F0 = F0 * F2;
    F0 = F1 + F0;
    R1 = DM(14, I7);
    F1 = F1 + F0;                                       // out_s += z
    DM(14, I7) = R1;
    F0 = F11 + F0;                                      // aux_s += y + z
    R1 = DM(15, I7);
    F1 = F1 + F0;
    DM(15, I7) = R1;
    R0 = DM(10, I7);
    R1 = 0;
    F2 = -F0;
    COMP(F0, F1);
    IF GE R2 = R0 OR R0;
    R1 = 0x3F800000;                                    // one
    F2 = F1 - F2;                                       // x = path_x[ij] * (1.0f - absf(x_offset)) + x_offset
    R3 = DM(I2, M6);
    F3 = F3 * F2;
    F10 = F3 + F0;
    R11 = DM(I3, M6);                                   // y = path_y[ij]
    R12 = DM(12, I7);
    CALL _tk_ter;                                       // z0 = terrain(x, y, zz_integral)
    DM(16, I7) = R0;
    R12 = DM(12, I7);
    R1 = 1;
    .NOCOMPRESS;
    R12 = R12 + R1;
    .COMPRESS;
    CALL _tk_ter;                                       // z1 = terrain(x, y, zz_integral + 1)
    R1 = DM(16, I7);
    F0 = F0 - F1;                                       // z = z0 + (z1 - z0) * zz_fractional
    R2 = DM(13, I7);
    F0 = F0 * F2;
    F0 = F1 + F0;
    R1 = DM(14, I7);
    F1 = F1 + F0;                                       // out_s += z
    DM(14, I7) = R1;
    F0 = F11 + F0;                                      // aux_s += y + z
    R1 = DM(15, I7);
    F1 = F1 + F0;
    DM(15, I7) = R1;
    R0 = DM(14, I7);
    R1 = 0x3F000000;                                    // half
    F0 = F1 * F0;                                       // out[i] = kScale * out_s
    DM(I0, M6) = R0;
    R0 = DM(15, I7);
    R1 = 0x3E800000;                                    // q
    F0 = F1 * F0;                                       // aux[i] = terrain_sine(1.0f + 0.5f * kScale * aux_s)
    R1 = 0x3F800000;                                    // one
    F0 = F1 + F0;
    CALL _tk_sin;
    DM(I1, M6) = R0;
    R0 = DM(9, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(9, I7) = R0;
    IF NE JUMP _tk_loop;
_tk_done:
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,17)(NW);
    L5 = DM(1, I7);
    L4 = DM(2, I7);
    L3 = DM(3, I7);
    L2 = DM(4, I7);
    L1 = DM(5, I7);
    L0 = DM(6, I7);
    M6 = DM(7, I7);
    I5 = DM(8, I7);
    I3 = DM(9, I7);
    I2 = DM(10, I7);
    I1 = DM(11, I7);
    I0 = DM(12, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
_tk_sin:
    R1 = 0;
    COMP(F0, F1);                                       // phase < 0.0f: wrap by its integer part plus one
    IF GE JUMP _tks_s;
    R1 = TRUNC F0;                                      // (int)phase (<= 0)
    R2 = 0;
    COMP(R1, R2);                                       // itof: i < 0 ? -itof_nonneg(-i) : itof_nonneg(i)
    IF GE JUMP _tks_p;
    R1 = -R1;
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = -F1;
    JUMP _tks_d;
_tks_p:
    R1 = R15 OR R1;
    F1 = F1 - F15;
_tks_d:
    F0 = F0 - F1;                                       // phase - itof((int)phase) + 1.0f
    R1 = 0x3F800000;                                    // one
    F0 = F0 + F1;
    COMP(F0, F1);                                       // phase >= 1.0f: phase -= 1.0f
    IF LT JUMP _tks_s;
    F0 = F0 - F1;
_tks_s:
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;                                    // 512
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R0 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F0;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F0 + F2;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tk_ter:
    R0 = 0;
    COMP(R12, R0);
    IF EQ JUMP _tkt0;
    R0 = 1;
    COMP(R12, R0);
    IF EQ JUMP _tkt1;
    R0 = 2;
    COMP(R12, R0);
    IF EQ JUMP _tkt2;
    R0 = 3;
    COMP(R12, R0);
    IF EQ JUMP _tkt3;
    R0 = 4;
    COMP(R12, R0);
    IF EQ JUMP _tkt4;
    R0 = 5;
    COMP(R12, R0);                                      // 5..7: terrain_lookup_wt
    IF LT JUMP _tkt_z;
    R0 = 7;
    COMP(R12, R0);
    IF LE JUMP _tkt_wt;
_tkt_z:
    R0 = 0;                                             // return 0.0f
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt0:
    R1 = 0x3FA2F1AA;                                    // 1.273
    F0 = F10 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    R1 = 0x40000000;                                    // two
    F0 = F0 * F1;                                       // squash: x *= a; x / (1.0f + absf(x))
    R4 = 0;
    F5 = -F0;
    COMP(F0, F4);
    IF GE R5 = R0 OR R0;
    R1 = 0x3F800000;                                    // one
    F5 = F1 + F5;
    R7 = 0x40000000;                                    // two
    F6 = RECIPS F5;
    F8 = F5 * F6;                                       // selcc division
    F8 = F7 - F8;
    F6 = F6 * F8;
    F8 = F5 * F6;
    F8 = F7 - F8;
    F6 = F6 * F8;
    F7 = F0 * F6;
    F8 = F5 * F7;
    F8 = F0 - F8;
    F8 = F8 * F6;
    F4 = F7 + F8;
    R1 = 0x3FC91687;                                    // 1.571
    F0 = F10 + F1;
    F0 = F11 * F0;
    R1 = 0x3F23126F;                                    // 0.637
    F0 = F0 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    F4 = F4 - F0;
    R1 = 0x3F11EB85;                                    // 0.57
    F0 = F4 * F1;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt1:
    F4 = F10 * F11;                                     // xy = x * y
    F0 = F10 + F11;                                     // (x + y) * 0.637f
    R1 = 0x3F23126F;                                    // 0.637
    F0 = F0 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    F5 = F4 * F4;
    R1 = 0x3E4CCCCD;                                    // 0.2
    F5 = F1 + F5;
    R7 = 0x40000000;                                    // two
    F6 = RECIPS F5;
    F8 = F5 * F6;                                       // selcc division
    F8 = F7 - F8;
    F6 = F6 * F8;
    F8 = F5 * F6;
    F8 = F7 - F8;
    F6 = F6 * F8;
    F7 = F0 * F6;
    F8 = F5 * F7;
    F8 = F0 - F8;
    F8 = F8 * F6;
    F0 = F7 + F8;
    R1 = 0x3E22D0E5;                                    // 0.159
    F0 = F0 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt2:
    F4 = F10 * F11;                                     // xy = x * y
    R1 = 0x4018C49C;                                    // 2.387
    F0 = F1 * F4;                                       // 2.387f * xy
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    F5 = F4 * F4;
    R1 = 0x3EB33333;                                    // 0.350
    F5 = F1 + F5;
    R7 = 0x40000000;                                    // two
    F6 = RECIPS F5;
    F8 = F5 * F6;                                       // selcc division
    F8 = F7 - F8;
    F6 = F6 * F8;
    F8 = F5 * F6;
    F8 = F7 - F8;
    F6 = F6 * F8;
    F7 = F0 * F6;
    F8 = F5 * F7;
    F8 = F0 - F8;
    F8 = F8 * F6;
    F0 = F7 + F8;
    R1 = 0x3E22D0E5;                                    // 0.159
    F0 = F0 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt3:
    F4 = F10 * F11;                                     // xy
    R1 = 0x3E800000;                                    // q
    F5 = F10 - F1;                                      // xys = (x - 0.25f) * (y + 0.25f)
    F6 = F11 + F1;
    F5 = F5 * F6;
    R1 = 0x40A00000;                                    // five
    F5 = F1 * F5;
    R3 = 0;
    F6 = -F5;
    COMP(F5, F3);
    IF GE R6 = R5 OR R5;
    R1 = 0x40000000;                                    // two
    F6 = F1 + F6;
    R7 = 0x40000000;                                    // two
    F5 = RECIPS F6;
    F8 = F6 * F5;                                       // selcc division
    F8 = F7 - F8;
    F5 = F5 * F8;
    F8 = F6 * F5;
    F8 = F7 - F8;
    F5 = F5 * F8;
    F7 = F4 * F5;
    F8 = F6 * F7;
    F8 = F4 - F8;
    F8 = F8 * F5;
    F0 = F7 + F8;
    R1 = 0x40CBB646;                                    // 6.366
    F0 = F0 * F1;
    R1 = 0x40800000;                                    // four
    F0 = F1 + F0;
    CALL _tk_sin;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt4:
    R3 = 0;
    R1 = 0x3E800000;                                    // q
    F5 = F11 - F1;
    F6 = -F5;
    COMP(F5, F3);
    IF GE R6 = R5 OR R5;
    R1 = 0x3E2E147B;                                    // 0.170
    F6 = F1 + F6;
    R2 = 0x3E22D0E5;                                    // 0.159
    R7 = 0x40000000;                                    // two
    F5 = RECIPS F6;
    F8 = F6 * F5;                                       // selcc division
    F8 = F7 - F8;
    F5 = F5 * F8;
    F8 = F6 * F5;
    F8 = F7 - F8;
    F5 = F5 * F8;
    F7 = F2 * F5;
    F8 = F6 * F7;
    F8 = F2 - F8;
    F8 = F8 * F5;
    F4 = F7 + F8;
    R1 = 0x3F000000;                                    // half
    F5 = F10 + F1;
    R1 = 0x3FC00000;                                    // 1.5
    F6 = F11 + F1;
    F5 = F5 * F6;
    R3 = 0;
    F6 = -F5;
    COMP(F5, F3);
    IF GE R6 = R5 OR R5;
    R1 = 0x3EB33333;                                    // 0.350
    F6 = F1 + F6;
    R2 = 0x3EF43958;                                    // 0.477
    R7 = 0x40000000;                                    // two
    F5 = RECIPS F6;
    F8 = F6 * F5;                                       // selcc division
    F8 = F7 - F8;
    F5 = F5 * F8;
    F8 = F6 * F5;
    F8 = F7 - F8;
    F5 = F5 * F8;
    F7 = F2 * F5;
    F8 = F6 * F7;
    F8 = F2 - F8;
    F8 = F8 * F5;
    F0 = F7 + F8;
    F0 = F4 + F0;
    R1 = 0x40800000;                                    // four
    F0 = F0 + F1;
    CALL _tk_sin;
    .NOCOMPRESS;
    RTS (DB);                                           // the stock return form is delayed
    .COMPRESS;
    NOP;
    NOP;
_tkt_wt:
    R1 = 0x3F800000;                                    // one
    F4 = F11 + F1;                                      // sample = (y + 1.0f) * 0.5f * 128.0f
    R2 = 0x3F000000;                                    // half
    F4 = F4 * F2;
    R3 = 0x43000000;                                    // 128
    F4 = F4 * F3;
    F5 = F10 + F1;                                      // wt = (x + 1.0f) * 0.5f * 63.0f
    F5 = F5 * F2;
    R6 = 0x427C0000;                                    // 63
    F5 = F5 * F6;
    R0 = 0;
_tkt_w1:
    COMP(F4, F0);                                       // while (sample < 0.0f) sample += 128.0f
    IF GE JUMP _tkt_w2;
    F4 = F4 + F3;
    JUMP _tkt_w1;
_tkt_w2:
    R1 = 0x43020000;                                    // 130
_tkt_w3:
    COMP(F4, F1);                                       // while (sample >= 130.0f) sample -= 128.0f
    IF LT JUMP _tkt_w4;
    F4 = F4 - F3;
    JUMP _tkt_w3;
_tkt_w4:
    COMP(F5, F0);                                       // if (wt < 0.0f) wt = 0.0f
    IF LT R5 = R0 OR R0;
    COMP(F5, F6);                                       // if (wt > 63.0f) wt = 63.0f
