    R6 = TRUNC F4;                                      // sample_integral
    R7 = R15 OR R6;
    F7 = F7 - F15;
    F4 = F4 - F7;                                       // sample_fractional
    R7 = TRUNC F5;                                      // wt_integral
    R8 = R15 OR R7;
    F8 = F8 - F15;
    F5 = F5 - F8;                                       // wt_fractional
    R0 = 7;
    .NOCOMPRESS;
    R0 = R0 - R12;                                      // bank = 2 - (index - 5)
    .COMPRESS;
    R1 = LSHIFT R0 BY 13;                               // bank * (64 * 132) = bank * 8192 + bank * 256
    R0 = LSHIFT R0 BY 8;
    .NOCOMPRESS;
    R1 = R1 + R0;
    .COMPRESS;
    R0 = LSHIFT R7 BY 7;                                // wt_integral * 132 = * 128 + * 4
    R2 = LSHIFT R7 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R2;
    .COMPRESS;
    .NOCOMPRESS;
    R1 = R1 + R0;
    .COMPRESS;
    .NOCOMPRESS;
    R8 = R1 + R6;                                       // base
    .COMPRESS;
    R0 = LSHIFT R8 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R13;
    .COMPRESS;
    I4 = R0;
    R0 = 0;                                             // (DAG gap)
    R1 = 0;
    R0 = DM(I4, M5);                                    // a
    R1 = DM(1, I4);                                     // b
    R2 = DM(2, I4);                                     // c
    F3 = F1 - F0;                                       // b - a
    F2 = F2 - F1;                                       // c - b - b + a
    F2 = F2 - F1;
    F2 = F2 + F0;
    F2 = F2 * F4;
    F6 = F3 + F2;
    R0 = 63;
    COMP(R7, R0);                                       // wt_integral >= 63: xy1 = xy0
    IF LT JUMP _tkt_w5;
    R0 = PASS R6;
    JUMP _tkt_w6;
_tkt_w5:
    R0 = 132;
    .NOCOMPRESS;
    R8 = R8 + R0;
    .COMPRESS;
    R0 = LSHIFT R8 BY 2;
    .NOCOMPRESS;
    R0 = R0 + R13;
    .COMPRESS;
    I4 = R0;
    R0 = 0;                                             // (DAG gap)
    R1 = 0;
    R0 = DM(I4, M5);                                    // a
    R1 = DM(1, I4);                                     // b
    R2 = DM(2, I4);                                     // c
    F3 = F1 - F0;                                       // b - a
    F2 = F2 - F1;                                       // c - b - b + a
    F2 = F2 - F1;
    F2 = F2 + F0;
    F2 = F2 * F4;
    F0 = F3 + F2;
_tkt_w6:
    F0 = F0 - F6;                                       // (xy0 + (xy1 - xy0) * wt_fractional) * value_scale
